-- ============================================================================
-- FlexAt Home — exercise catalog seed
--
-- GENERATED FILE. Do not edit by hand.
-- Regenerate with:  npm run seed:generate
--
-- Source of truth: src/lib/domain/exercise-seed.ts
--
-- The catalog is reference data shared by every user. It is inserted with a
-- fixed id derived from the slug so re-running this file is idempotent and the
-- app's local ids line up with the cloud ones.
-- ============================================================================

begin;

insert into public.exercises (
  id, name, slug, description, body_parts, primary_muscles, secondary_muscles,
  difficulty, exercise_type, equipment_required, instructions, form_cues,
  common_mistakes, breathing_instruction, recommended_sets, recommended_reps,
  recommended_duration, recommended_rest, safety_notes
) values
  ('5f9a6108-0146-5cd2-9b0f-756f1b5573b8', 'Push-Up', 'push-up', 'The reference horizontal press for home training. Scales from a wall push to a full floor push by changing hand and body height.', ARRAY['chest', 'shoulders', 'arms']::body_part[], ARRAY['chest']::muscle_group[], ARRAY['triceps', 'deltoids']::muscle_group[], 'beginner'::fitness_level, 'push_up'::exercise_type, 'none'::equipment, ARRAY['Place hands on the floor slightly wider than shoulder width, fingers spread.', 'Walk the feet back until the body forms a straight line from head to heels.', 'Bend the elbows to about 45 degrees from the torso and lower the chest.', 'Press the floor away until the elbows lock out, without letting the hips sag.']::text[], ARRAY['Squeeze the glutes so the hips stay level with the shoulders.', 'Elbows point back at roughly 45 degrees, not straight out to the sides.', 'Look at a spot just ahead of the hands, not at the floor.']::text[], ARRAY['Letting the hips sag or pike, which shifts load away from the chest.', 'Flaring the elbows to 90 degrees, which strains the shoulder.', 'Half repping at the bottom, where the chest never touches the floor.']::text[], 'Inhale as you lower, exhale as you press up. Do not hold your breath at the bottom.', 3, 12, null, 60, 'Stop if you feel sharp pain in the shoulder or wrist. If a full push-up is too hard, use wall or incline push-ups rather than dropping to the knees with a sagging hip.'),
  ('8a364438-6a23-5cb3-9475-ca7fd6b50d2c', 'Incline Push-Up', 'incline-push-up', 'A wall or counter-height push-up. The vertical angle reduces the load, making it the standard entry point rather than a lesser exercise.', ARRAY['chest', 'shoulders', 'arms']::body_part[], ARRAY['chest']::muscle_group[], ARRAY['triceps', 'deltoids']::muscle_group[], 'beginner'::fitness_level, 'push_up'::exercise_type, 'none'::equipment, ARRAY['Stand facing a wall or sturdy counter, feet a step back from it.', 'Place hands on the surface at chest height and walk the feet back to a straight line.', 'Lower the chest toward the surface, keeping the body rigid.', 'Press away to a straight arm.']::text[], ARRAY['Keep a straight line from heels to head.', 'Lower under control, not by dropping.']::text[], ARRAY['Feet drifting too close, making it too easy.']::text[], 'Inhale down, exhale up.', 3, 15, null, 45, 'Use a wall or counter that cannot slide. Do not lean on a rolling surface.'),
  ('b3a2e7ff-8e3f-5d0b-9b17-641108e33779', 'Pike Push-Up', 'pike-push-up', 'The closest bodyweight approximation to an overhead press. It builds shoulder pressing strength, but it does not reproduce the loaded range of a machine press.', ARRAY['shoulders', 'arms', 'chest']::body_part[], ARRAY['deltoids']::muscle_group[], ARRAY['triceps', 'chest', 'rotator_cuff']::muscle_group[], 'intermediate'::fitness_level, 'push_up'::exercise_type, 'none'::equipment, ARRAY['From a push-up position, walk the feet in toward the hands and lift the hips high.', 'Set the hands slightly wider than shoulder width, fingers forward or rotated slightly out.', 'Lower the crown of the head toward the floor between or just in front of the hands.', 'Press back up to the starting pike.']::text[], ARRAY['Hips stay high; the movement is a vertical press, not a push-up with bent hips.', 'Neck stays neutral — look at the floor slightly ahead of the hands.']::text[], ARRAY['Letting the hips drop, which turns the movement into an incline push-up.', 'Craning the neck to look forward.']::text[], 'Inhale down, exhale up.', 3, 8, null, 75, 'Stop at any sharp pain at the front of the shoulder. If the hands are uncomfortable, use parallette-style hands on the floor rather than a spiked surface.'),
  ('9d9adbe9-ebf0-59f6-9d00-e7c0373c809a', 'Handstand Wall Drill', 'handstand-wall-drill', 'Progressive shoulder strength and balance toward a freestanding handstand. The wall removes balance as a limiting factor so the shoulders and core can be trained honestly.', ARRAY['shoulders', 'arms', 'core']::body_part[], ARRAY['deltoids']::muscle_group[], ARRAY['triceps', 'abs', 'forearms']::muscle_group[], 'advanced'::fitness_level, 'balance'::exercise_type, 'none'::equipment, ARRAY['Face a wall and place the hands on the floor about 20 cm from it.', 'Kick one foot up to the wall, then the other, until stacked over the hands.', 'Hold with the hips stacked over the shoulders and the ribs pulled down.', 'Come down one foot at a time.']::text[], ARRAY['Push the floor away hard to create shoulder elevation.', 'Squeeze the glutes and quads to keep the line vertical.']::text[], ARRAY['Arching the lower back to get the hips up, which loads the lumbar spine.', 'Sticking the elbows out, which limits the pressing position.']::text[], 'Exhale during the kick-up, then breathe slowly during holds.', 5, 5, 20, 90, 'This is a shoulder-balance drill, not a spinal-loading exercise. Do not attempt it with any neck injury. Come down immediately if the lower back arches.'),
  ('f6b8b822-0629-5fde-a6e4-25607d392fe1', 'Bodyweight Triceps Extension', 'bodyweight-triceps-extension', 'Elbow-extension strength without weights. The angle of the upper arm changes the difficulty, so a floor variation is much harder than a wall variation.', ARRAY['arms']::body_part[], ARRAY['triceps']::muscle_group[], ARRAY['abs']::muscle_group[], 'intermediate'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Start in a push-up position with the hands slightly behind shoulder level.', 'Keeping the elbows bent and pointing back, bend only at the elbows to lower the chest.', 'Extend the elbows to press back up.']::text[], ARRAY['The upper arms stay fixed; only the forearms move.', 'Hips do not rise or fall during the set.']::text[], ARRAY['Letting the elbows flare, which turns it into a normal push-up.']::text[], 'Inhale down, exhale up.', 3, 10, null, 60, 'Keep the wrists under the shoulders and neutral. Stop at any wrist pain.'),
  ('0734dd4c-5a5a-538f-b415-7733a08da17d', 'Wall Triceps Extension', 'wall-triceps-extension', 'The accessible version of the bodyweight triceps extension: face away from a wall and lower only the upper body below the hands.', ARRAY['arms']::body_part[], ARRAY['triceps']::muscle_group[], '{}'::muscle_group[], 'beginner'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Stand facing away from a wall with the feet about a step forward.', 'Place the hands on the wall at waist height and lean the body forward into a straight line.', 'Bend the elbows to lower the body toward a right angle, keeping the upper arms against the wall.', 'Press back up.']::text[], ARRAY['Only the body below the hands moves.']::text[], ARRAY['Arching the lower back to lower further.']::text[], 'Inhale down, exhale up.', 3, 12, null, 45, 'Do not lower so far that the lower back rounds. A partial range is safer than a deep one.'),
  ('ef84d1d0-2089-5738-b68d-cb1f7f93960f', 'Plank Shoulder Tap', 'plank-shoulder-tap', 'Anti-rotation core work that also loads one shoulder at a time, so it trains the trunk to resist twisting under uneven load.', ARRAY['core', 'shoulders', 'chest']::body_part[], ARRAY['abs']::muscle_group[], ARRAY['obliques', 'deltoids', 'chest']::muscle_group[], 'intermediate'::fitness_level, 'plank'::exercise_type, 'none'::equipment, ARRAY['Set up in a forearm plank with the feet slightly wider than the hips.', 'Shift weight into the right forearm and lift the left hand to tap the right shoulder.', 'Replace the hand and repeat on the other side.']::text[], ARRAY['Hips stay level; the body does not rotate toward the tapping hand.', 'Press the floor away with the supporting arm to stop the shoulder from collapsing.']::text[], ARRAY['Hips rocking side to side with each tap.', 'Rounding the lower back.']::text[], 'Exhale as you tap, inhale as you replace.', 3, 20, null, 45, 'If the lower back sags, return to a static forearm plank first.'),
  ('13c9a6f3-08fb-5ee6-8da9-cabb906ba92e', 'Prone Y-T-W Raise', 'prone-y-t-w-raise', 'A face-down floor drill for the mid and upper back. Be honest about what this is: it trains the muscles that hold the shoulders back, but it cannot deliver the pulling volume of rows or pull-ups. It is a supplement to those, not a replacement.', ARRAY['back', 'shoulders']::body_part[], ARRAY['rhomboids', 'traps']::muscle_group[], ARRAY['rear_deltoids', 'erector_spine']::muscle_group[], 'beginner'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Lie face down on the floor with arms extended forward.', 'Lift the arms a few centimetres off the floor, palms down, forming a Y.', 'Draw the shoulder blades together and down, then hold for 2 seconds.', 'Repeat, then sweep the arms out to a T for the second letter, and back for the W.']::text[], ARRAY['Movement comes from the shoulder blades, not from throwing the arms up.', 'The neck stays down; you are looking at the floor the whole time.', 'Lift only a few centimetres — height is not the goal.']::text[], ARRAY['Yanking the arms up with momentum.', 'Craning the neck to look forward, which compresses the neck extensors.', 'Holding the breath and arching the lower back.']::text[], 'Inhale as the arms lower, exhale as you lift and hold.', 3, 10, null, 45, 'This is a low-load back exercise, not a substitute for a real pulling movement. Do not turn it into a hyperextension by lifting the legs and chest at the same time.'),
  ('83c0589f-543e-5a61-9bd7-ec0810f0a16a', 'Superman Hold', 'superman-hold', 'Spinal endurance for the posterior chain. Useful for posture and for balancing out a lot of pushing and sitting work.', ARRAY['back', 'core', 'full_body']::body_part[], ARRAY['erector_spine', 'glutes']::muscle_group[], ARRAY['traps', 'hamstrings']::muscle_group[], 'beginner'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Lie face down with arms extended overhead and legs straight.', 'Lift the arms, chest, and legs a few centimetres off the floor at the same time.', 'Hold for the target time, breathing throughout.']::text[], ARRAY['Lift from the upper back rather than by pulling on the neck.', 'Gaze stays down at the floor throughout.']::text[], ARRAY['Lifting the legs high, which turns the lower back into a lever.', 'Holding the breath.']::text[], 'Keep breathing steadily throughout the hold. Do not hold your breath.', 3, null, 20, 45, 'Stop at any lower back pain. Keep the legs low rather than pushing height.'),
  ('33a9a5c5-f58e-5d70-80e5-f72ca4f1dace', 'Reverse Snow Angel', 'reverse-snow-angel', 'Thoracic mobility and upper-back range work. The prone position is a genuine limitation: without a pull-up bar there is no unloaded way to hang and decompress the spine.', ARRAY['back', 'shoulders']::body_part[], ARRAY['traps', 'rhomboids']::muscle_group[], ARRAY['erector_spine']::muscle_group[], 'beginner'::fitness_level, 'stretch'::exercise_type, 'none'::equipment, ARRAY['Lie face down, arms out to the sides in a T, palms down.', 'Keeping the legs and hips still, sweep the arms up and back to bring the hands toward each other.', 'Open back out to the start, then reverse the path.']::text[], ARRAY['Movement is slow and comes from the upper back, not the neck.']::text[], ARRAY['Rushing the range.', 'Lifting the legs to create momentum.']::text[], 'Exhale as the arms sweep up, inhale on the way down.', 2, 10, null, 30, 'Stay well within a comfortable range. This is mobility, not a stretch contest.'),
  ('984c06dd-e1e7-58e7-9301-cb1b2733b5a3', 'Quadruped Rock-Back', 'quadruped-rock-back', 'A safe, equipment-free way to train the lats and upper back in a lengthened position, which most bodyweight pulling cannot reach.', ARRAY['back', 'shoulders']::body_part[], ARRAY['lats']::muscle_group[], ARRAY['traps', 'rhomboids', 'abs']::muscle_group[], 'beginner'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Set up on hands and knees with hands under the shoulders.', 'Press the floor away and shift the hips back toward the heels, keeping the arms long.', 'Return to all fours without dropping the hips.']::text[], ARRAY['The hands stay planted and the arms stay straight — this is a hip hinge, not a sit-up.', 'Press the floor away to keep the shoulders active.']::text[], ARRAY['Bending the elbows and turning it into a push-up.', 'Rounding the back.']::text[], 'Inhale as the hips shift back, exhale to return.', 3, 12, null, 30, 'Keep the neck in line with the spine. Do not force the hip shift if the knees or wrists object.'),
  ('95c5865c-eb0f-56d2-b637-0cf8c4a70dbb', 'Doorway or Table Row (Self-Resisted Isometric)', 'doorway-or-table-row-self-resisted-isometric', 'An isometric back contraction using a fixed surface. It is a genuine option with no equipment at home, but it produces far less back volume than an actual row, so treat it as a warm-up or a supplement.', ARRAY['back']::body_part[], ARRAY['lats', 'rhomboids']::muscle_group[], ARRAY['biceps', 'traps']::muscle_group[], 'beginner'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Sit on the floor facing a sturdy table edge, knees bent, feet flat.', 'Loop a towel around the table leg and hold both ends in your hands.', 'Sit up tall and pull the elbows back, squeezing the shoulder blades together.', 'Hold the contraction for the target time, then release slowly.']::text[], ARRAY['Ribs stay down; the movement is a shoulder-blade retraction, not a lean back.', 'Pull with the elbows, not by lifting the shoulders.']::text[], ARRAY['Leaning back to use body weight.', 'Shrugging the shoulders.']::text[], 'Exhale during the pull, breathe slowly during the hold. Do not hold your breath.', 3, null, 15, 45, 'Use a table bolted down or a low, heavy, non-sliding piece of furniture. A free-standing lightweight table can tip. This is an isometric, so it builds less back than a dynamic row.'),
  ('1b1a21ef-675e-563d-bfcd-eb921d71e377', 'Prone Scapular Retraction', 'prone-scapular-retraction', 'Isolates the shoulder blades. A good default back exercise when nothing else is available, and safe for most beginners.', ARRAY['back', 'shoulders']::body_part[], ARRAY['rhomboids', 'traps']::muscle_group[], '{}'::muscle_group[], 'beginner'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Lie face down with the arms bent and the hands beside the ribs.', 'Draw the shoulder blades together and slightly down.', 'Hold 2 seconds, then relax completely.']::text[], ARRAY['Elbows stay bent and close to the body.']::text[], ARRAY['Shrugging instead of retracting.']::text[], 'Exhale on the retraction, inhale on the release.', 3, 12, null, 30, 'Small, pain-free range only.'),
  ('e398de24-5fc6-5778-9c1c-99922a707eb6', 'Bodyweight Squat', 'bodyweight-squat', 'The fundamental lower-body pattern. Depth is limited by ankle and hip mobility, and the load stays below what a loaded barbell squat provides, so progress comes from tempo and reps rather than weight.', ARRAY['legs', 'glutes']::body_part[], ARRAY['quads', 'glutes']::muscle_group[], ARRAY['hamstrings', 'abs']::muscle_group[], 'beginner'::fitness_level, 'bodyweight_squat'::exercise_type, 'none'::equipment, ARRAY['Stand with feet about shoulder width, toes turned slightly out.', 'Take a breath, brace the core, and push the hips back and down.', 'Descend until the thighs are at least parallel, or to your comfortable depth.', 'Drive through the whole foot to stand up.']::text[], ARRAY['Knees track over the toes.', 'Chest stays up and the lower back stays neutral.', 'Spread the floor with the feet to keep the knees from caving.']::text[], ARRAY['Heels lifting off the floor.', 'Rounding the lower back to get lower.', 'Knees collapsing inward on the way up.']::text[], 'Inhale at the top or mid-descent, exhale as you stand.', 3, 15, null, 60, 'Depth is not the goal — quality is. Do not round the lower back to reach depth, and do not go below a depth you can control.'),
  ('02298c15-f060-5bb0-a10f-72dbfcca3d8a', 'Split Squat', 'split-squat', 'Single-leg work that exposes and corrects side-to-side imbalances. Harder than a bilateral squat at the same nominal difficulty, because balance and the weaker leg both cost you.', ARRAY['legs', 'glutes']::body_part[], ARRAY['quads', 'glutes']::muscle_group[], ARRAY['hamstrings', 'adductors']::muscle_group[], 'intermediate'::fitness_level, 'lunge'::exercise_type, 'none'::equipment, ARRAY['Step one foot forward about two foot lengths and stand tall.', 'Lower the back knee toward the floor, keeping the front heel down.', 'Drive up through the front heel to return to standing.', 'Complete all reps on one side, then switch.']::text[], ARRAY['The front shin stays roughly vertical.', 'Torso stays upright, hips square to the front.']::text[], ARRAY['Pushing off the back foot.', 'Leaning forward over the front thigh.']::text[], 'Inhale down, exhale up.', 3, 10, null, 60, 'Hold a wall for balance if needed. The back knee should not slam into the floor; lower within a range you control.'),
  ('c49edc52-0d09-5d3c-b0b8-964a19d18ccf', 'Reverse Lunge', 'reverse-lunge', 'Knee-friendly alternative to the forward lunge, because the leading knee is not driven forward over the toes.', ARRAY['legs', 'glutes']::body_part[], ARRAY['quads', 'glutes']::muscle_group[], ARRAY['hamstrings']::muscle_group[], 'beginner'::fitness_level, 'lunge'::exercise_type, 'none'::equipment, ARRAY['Stand tall with feet hip width.', 'Step one foot straight back and lower the back knee toward the floor.', 'Push through the front heel to return.', 'Switch legs after the set.']::text[], ARRAY['Torso stays tall.', 'The front knee tracks over the middle toes.']::text[], ARRAY['Leaning forward.', 'Stepping back too short, which over-loads the front knee.']::text[], 'Inhale down, exhale up.', 3, 10, null, 60, 'Keep the step long enough that the front shin stays near vertical.'),
  ('a9ecf70c-8732-5387-9af8-2f28a306a0a0', 'Bulgarian Split Squat', 'bulgarian-split-squat', 'A demanding single-leg squat progression. The rear foot is elevated on a low stable surface, which requires one piece of household furniture and no purchased equipment.', ARRAY['legs', 'glutes']::body_part[], ARRAY['quads', 'glutes']::muscle_group[], ARRAY['hamstrings', 'abs']::muscle_group[], 'advanced'::fitness_level, 'lunge'::exercise_type, 'none'::equipment, ARRAY['Stand with the front foot about two foot lengths ahead of a low, stable step or chair.', 'Rest the top of the rear foot on the step.', 'Lower the back knee toward the floor, keeping the torso upright.', 'Drive up through the front heel.']::text[], ARRAY['The front shin stays close to vertical.', 'The hips stay square to the front rather than rotating open.']::text[], ARRAY['Stepping too close to the step, which jams the front knee.', 'Twisting the hips toward the working leg.']::text[], 'Inhale down, exhale up.', 3, 8, null, 90, 'Use a low, stable, non-rolling surface and test it before loading it. Skip this if the balance demand is too high for a solid position.'),
  ('bbe7c257-1df6-5848-9a1b-c28eff694655', 'Wall Sit', 'wall-sit', 'Quadriceps endurance with almost no balance demand, which makes it a good fit for a beginner or a session with a time cap.', ARRAY['legs']::body_part[], ARRAY['quads']::muscle_group[], ARRAY['glutes', 'abs']::muscle_group[], 'beginner'::fitness_level, 'bodyweight_squat'::exercise_type, 'none'::equipment, ARRAY['Stand with the back flat against a wall.', 'Walk the feet forward and slide down until the knees are bent to about 90 degrees.', 'Keep the lower back flat against the wall and hold.']::text[], ARRAY['Thighs roughly parallel to the floor.', 'Weight in the heels.']::text[], ARRAY['Arching the lower back to get lower.', 'Holding the breath.']::text[], 'Breathe continuously throughout the hold.', 3, null, 30, 45, 'Slide only as far as you can hold without arching the back. Lower quad depth is fine.'),
  ('033a04de-821b-5860-92e2-7b4e5f86806f', 'Pistol Squat Progression', 'pistol-squat-progression', 'Progressive single-leg loading using bodyweight. The honest version is a slow, controlled single-leg squat to a chair, not an unsupported free-standing pistol.', ARRAY['legs', 'glutes']::body_part[], ARRAY['quads', 'glutes']::muscle_group[], ARRAY['hamstrings', 'adductors', 'abs']::muscle_group[], 'advanced'::fitness_level, 'bodyweight_squat'::exercise_type, 'none'::equipment, ARRAY['Stand in front of a chair, on one leg, with the other foot lifted in front of the body.', 'Lower slowly until the butt just touches the chair, keeping the working heel down.', 'Pause, then stand back up on the same leg without sitting.']::text[], ARRAY['The working knee tracks over the middle toes.', 'The free leg stays lifted, not swinging.']::text[], ARRAY['Falling backwards onto the chair and sitting.', 'Letting the knee cave inward.']::text[], 'Inhale down, exhale up.', 3, 6, null, 90, 'Have a wall or counter within reach. This progression is not appropriate for anyone with knee pain or poor balance — use a regular split squat instead.'),
  ('33882c98-42ed-569b-93e9-c9658c7ef2c0', 'Standing Calf Raise', 'standing-calf-raise', 'Calf strength and ankle resilience using any flat surface as a reference.', ARRAY['legs']::body_part[], ARRAY['calves']::muscle_group[], '{}'::muscle_group[], 'beginner'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Stand with the ball of the foot on the edge of a step, the heel hanging free.', 'Rise onto the balls of the feet as high as possible.', 'Lower until the heels drop below the level of the step.']::text[], ARRAY['Rise and lower slowly.', 'Keep the knees straight for the gastrocnemius.']::text[], ARRAY['Bouncing out of the bottom.', 'Using the hands for momentum.']::text[], 'Exhale as you rise, inhale as you lower.', 3, 15, null, 30, 'Hold a wall for balance. Stop at any sharp calf or Achilles pain.'),
  ('6c78dcdd-014a-5300-aadf-1cc1322abf11', 'Glute Bridge', 'glute-bridge', 'Hip extension and trunk control from the floor. Unloads the spine, which makes it a good default for days when the back is not up to a standing load.', ARRAY['glutes', 'core']::body_part[], ARRAY['glutes']::muscle_group[], ARRAY['hamstrings', 'abs', 'erector_spine']::muscle_group[], 'beginner'::fitness_level, 'bridge'::exercise_type, 'none'::equipment, ARRAY['Lie on your back with knees bent and heels close to the buttock.', 'Press through the heels and lift the hips until the body forms a straight line.', 'Squeeze the glutes for a second at the top, then lower under control.']::text[], ARRAY['The ribs stay down — do not arch the lower back to lift higher.', 'Drive with the glutes, not by pushing the hips with the lower back.']::text[], ARRAY['Hyperextending the lower back at the top.', 'Pushing through the toes.']::text[], 'Exhale as the hips rise, inhale as they lower.', 3, 15, null, 45, 'Stop at any lower back or hip pain. A smaller range is fine.'),
  ('e8f4d5bd-aa90-5530-8754-5d04508e4b22', 'Single-Leg Glute Bridge', 'single-leg-glute-bridge', 'Unilateral version of the bridge, which removes the stronger side from the equation and is harder than it looks.', ARRAY['glutes']::body_part[], ARRAY['glutes']::muscle_group[], ARRAY['hamstrings', 'abs']::muscle_group[], 'intermediate'::fitness_level, 'bridge'::exercise_type, 'none'::equipment, ARRAY['Lie on your back with knees bent.', 'Extend one leg, keeping the foot flat on the floor for balance.', 'Drive through the planted heel and lift the hips.', 'Lower under control and switch legs.']::text[], ARRAY['The pelvis stays level — it should not tip to the lifted side.']::text[], ARRAY['Rotating the pelvis up toward the free leg.']::text[], 'Exhale up, inhale down.', 3, 10, null, 45, 'Keep the foot lightly on the floor for balance rather than lifting it high.'),
  ('8b211d69-ac5d-504e-aa3c-700b4a775e91', 'Fire Hydrant', 'fire-hydrant', 'Hip rotator and glute work on all fours. Targets the side of the hip that most desk and sitting routines neglect.', ARRAY['glutes', 'legs']::body_part[], ARRAY['glutes']::muscle_group[], ARRAY['adductors', 'abs']::muscle_group[], 'beginner'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Set up on hands and knees with hands under the shoulders.', 'Keeping the knee bent at 90 degrees, lift one knee out to the side.', 'Return under control and repeat, then switch sides.']::text[], ARRAY['The pelvis stays square and level.', 'Movement comes from the hip, not the lower back.']::text[], ARRAY['Lifting the leg so high the lower back takes over.', 'Rotating the torso.']::text[], 'Exhale as the knee lifts, inhale as it returns.', 3, 12, null, 30, 'Keep the range pain-free, especially with any hip or lower back history.'),
  ('3132a2d0-cca7-5c54-b0f9-92ade5060964', 'Clamshell', 'clamshell', 'Hip rotator strength in a low-risk position. Often the safest way to start loading the hip external rotators without aggravating the joint.', ARRAY['glutes', 'legs']::body_part[], ARRAY['glutes']::muscle_group[], '{}'::muscle_group[], 'beginner'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Lie on your side with the knees bent to about 45 degrees.', 'Keep the feet together and the pelvis stacked.', 'Rotate the top knee upward like a clam opening its shell.', 'Lower without letting the pelvis roll back.']::text[], ARRAY['The hips stay stacked — no backward roll.']::text[], ARRAY['Letting the pelvis roll back, which removes the hip work.']::text[], 'Exhale as the knee opens, inhale as it closes.', 3, 15, null, 30, 'Skip or reduce this if it causes pain at the front of the hip joint.'),
  ('a23b11c6-29fd-5e39-b072-29dd08d006e3', 'Thigh-Lift Hydrant Hold', 'thigh-lift-hydrant-hold', 'Isometric glute hold that is easier to load than a repetition-based bridge.', ARRAY['glutes']::body_part[], ARRAY['glutes']::muscle_group[], '{}'::muscle_group[], 'beginner'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Stand on one leg with a slight bend in the knee.', 'Hold onto a wall for balance if needed.', 'Squeeze the glute on the standing leg and hold.']::text[], ARRAY['Stand tall; the hold comes from the glute, not from leaning.']::text[], ARRAY['Leaning to the side to rest weight off the working leg.']::text[], 'Breathe steadily during the hold.', 3, null, 20, 30, 'Keep a hand on a wall until balance is reliable.'),
  ('e6c2c6e8-125b-5779-a8cf-dc07ffb666d0', 'Dead Bug', 'dead-bug', 'Anti-extension core work that teaches the trunk to stay still while the limbs move. Low spinal load, so it suits almost any starting point.', ARRAY['core']::body_part[], ARRAY['abs']::muscle_group[], ARRAY['obliques', 'hip_flexors']::muscle_group[], 'beginner'::fitness_level, 'crunch'::exercise_type, 'none'::equipment, ARRAY['Lie on your back with the arms straight up and the knees over the hips.', 'Press the lower back gently into the floor.', 'Lower one arm overhead and the opposite leg toward the floor, keeping the back flat.', 'Return and switch sides.']::text[], ARRAY['The lower back stays in contact with the floor the whole time.', 'Only the limbs move; the ribcage and pelvis stay fixed.']::text[], ARRAY['Letting the lower back arch off the floor.']::text[], 'Exhale as the limbs extend, inhale as they return.', 3, 10, null, 45, 'Reduce the range if the back lifts. This is always scaled down, never up.'),
  ('1e38c6ce-93d9-59d8-9baa-130e7c31a61e', 'Plank', 'plank', 'A straight-line isometric for the trunk. Learn it as a position, not a race — a rigid hold for 20 seconds beats a 60-second sagging one.', ARRAY['core']::body_part[], ARRAY['abs']::muscle_group[], ARRAY['obliques', 'deltoids', 'glutes']::muscle_group[], 'beginner'::fitness_level, 'plank'::exercise_type, 'none'::equipment, ARRAY['Set the forearms on the floor directly under the shoulders.', 'Extend the legs back, resting on the balls of the feet.', 'Squeeze the glutes and brace the core so the body forms one straight line.', 'Breathe normally and hold.']::text[], ARRAY['A straight line from the ears to the heels — no hips high, no hips low.', 'Push the floor away with the forearms to spread the shoulder blades.', 'Tuck the pelvis slightly rather than arching the lower back.']::text[], ARRAY['Hips piking up, which turns it into a pike push-up.', 'Lower back sagging, which loads the spine instead of the core.', 'Holding the breath.']::text[], 'Breathe continuously throughout the hold. Do not hold your breath.', 3, null, 30, 45, 'End the hold when the position degrades, not when the clock runs out. Come out to the knees if the back starts to sag.'),
  ('81e9ba31-0fb3-5dd4-add6-faa839f289c7', 'Forearm Plank with Reach', 'forearm-plank-with-reach', 'Plank variation that adds a shoulder and thoracic component without adding spinal load.', ARRAY['core', 'shoulders']::body_part[], ARRAY['abs']::muscle_group[], ARRAY['obliques', 'deltoids']::muscle_group[], 'intermediate'::fitness_level, 'plank'::exercise_type, 'none'::equipment, ARRAY['Set up in a forearm plank.', 'Without shifting the hips, slowly reach one arm forward and back.', 'Alternate arms while holding the plank position.']::text[], ARRAY['The hips do not move at all as the arm travels.']::text[], ARRAY['Hips rotating toward the reaching arm.']::text[], 'Exhale as the arm reaches forward.', 3, 16, null, 45, 'Regress to a static plank if the position cannot be held.'),
  ('82993434-dbf4-5357-be1d-76c523b678f7', 'Side Plank', 'side-plank', 'Anti-side-bending core work on one arm, which is harder than it appears. A good default for oblique and hip stability work.', ARRAY['core']::body_part[], ARRAY['obliques']::muscle_group[], ARRAY['abs', 'deltoids', 'glutes']::muscle_group[], 'intermediate'::fitness_level, 'plank'::exercise_type, 'none'::equipment, ARRAY['Lie on your side with the elbow directly under the shoulder.', 'Stack the feet, or stagger them for more stability.', 'Lift the hips so the body forms a straight line, then hold.']::text[], ARRAY['The body is one straight line — no hip dip or hip hike.', 'Push the floor away with the supporting forearm.']::text[], ARRAY['Hips sinking toward the floor.', 'Rolling forward onto the shoulder.']::text[], 'Breathe continuously during the hold.', 3, null, 20, 40, 'Drop the top leg to the floor for support if the shoulder cannot take the load. Stop at shoulder pain.'),
  ('9fbdaaf8-45fc-5425-805f-65b45ea0bd43', 'Hollow Hold', 'hollow-hold', 'A demanding anti-extension position. Only attempt it once a solid straight-body plank is comfortable, since it loads the lower back far more.', ARRAY['core']::body_part[], ARRAY['abs']::muscle_group[], ARRAY['hip_flexors']::muscle_group[], 'advanced'::fitness_level, 'plank'::exercise_type, 'none'::equipment, ARRAY['Lie on your back and press the lower back flat into the floor.', 'Lift the shoulder blades and legs off the floor, arms by the sides.', 'Hold the shape, keeping the lower back in contact with the floor.']::text[], ARRAY['The lower back never leaves the floor.']::text[], ARRAY['Hips rising and the lower back arching off the floor.']::text[], 'Exhale on setup, then breathe continuously during the hold.', 3, null, 20, 45, 'Not for anyone with a lower back injury. If the lower back cannot stay flat, the position is too advanced — return to a plank or a dead bug.'),
  ('b6783f77-2afa-5cdb-bee7-3d200e118982', 'Bicycle Crunch', 'bicycle-crunch', 'Rotation plus flexion, targeting the obliques while the legs move. Common, and effective when the rotation comes from the ribs rather than the elbow driving the knee.', ARRAY['core']::body_part[], ARRAY['obliques']::muscle_group[], ARRAY['abs', 'hip_flexors']::muscle_group[], 'intermediate'::fitness_level, 'crunch'::exercise_type, 'none'::equipment, ARRAY['Lie on your back with the hands lightly behind the head and the legs lifted.', 'Rotate the ribcage toward one knee while the opposite leg extends.', 'Return through the middle and switch sides.']::text[], ARRAY['The rotation comes from bringing the elbow to the knee, not from yanking the neck.', 'The lower back stays in contact with the floor.']::text[], ARRAY['Pulling on the neck with the hands.', 'Swinging the legs with momentum.']::text[], 'Exhale as you rotate toward the knee.', 3, 20, null, 45, 'If neck discomfort is an issue, keep the hands off the head. Skip with any neck or back injury.'),
  ('1d4ee627-4e6e-5f78-9b7d-04191fbb1488', 'Mountain Climber', 'mountain-climber', 'A dynamic core movement that also raises the heart rate, so it counts as conditioning as well as core work. Slow the tempo to make it a core exercise rather than a cardio one.', ARRAY['core', 'full_body']::body_part[], ARRAY['abs']::muscle_group[], ARRAY['obliques', 'deltoids', 'full_body']::muscle_group[], 'beginner'::fitness_level, 'mountain_climber'::exercise_type, 'none'::equipment, ARRAY['Set up in a tall plank with the hands under the shoulders.', 'Drive one knee toward the chest without lifting the hips.', 'Switch legs, keeping the shoulders stacked over the hands.']::text[], ARRAY['Hips stay level and slightly elevated — do not bounce them up and down.', 'Weight is in the hands, not the toes.']::text[], ARRAY['Hips bouncing high with each rep.', 'Rounding the back.']::text[], 'Exhale as the knee drives in.', 3, 20, null, 45, 'Drop to a slower tempo or to a standing knee drive if the wrists or back object.'),
  ('93d03767-ad7d-5bdf-bc31-bf84b72296e8', 'Standing Knee Raise', 'standing-knee-raise', 'The standing equivalent of a dead bug, and a better default for anyone whose back or wrists dislike floor work.', ARRAY['core']::body_part[], ARRAY['abs']::muscle_group[], ARRAY['obliques', 'hip_flexors']::muscle_group[], 'beginner'::fitness_level, 'crunch'::exercise_type, 'none'::equipment, ARRAY['Stand tall with the hands lightly on the hips.', 'Lift one knee toward the chest without leaning back.', 'Lower under control and switch sides.']::text[], ARRAY['The torso stays upright — the hip folds, the back does not arch.']::text[], ARRAY['Leaning back to bring the knee up.']::text[], 'Exhale as the knee lifts.', 3, 20, null, 30, 'Hold a wall for balance if needed.'),
  ('7afb49eb-5da2-55ea-b013-9ca1850fc865', 'Burpee', 'burpee', 'A full-body conditioning staple. The jump is optional and should be dropped whenever it is uncomfortable or the wrists cannot take it — the rest of the movement still works.', ARRAY['full_body']::body_part[], ARRAY['full_body']::muscle_group[], ARRAY['chest', 'quads', 'glutes', 'abs']::muscle_group[], 'intermediate'::fitness_level, 'burpee'::exercise_type, 'none'::equipment, ARRAY['Stand with feet shoulder width.', 'Squat down, place the hands on the floor, and jump or step the feet back into a plank.', 'Optional: lower the chest to the floor.', 'Jump or step the feet back in, stand up, and optionally jump with the arms overhead.']::text[], ARRAY['The lower back stays neutral in the plank — bring the knees in if the back sags.', 'Land softly on the balls of the feet.']::text[], ARRAY['Rounding the back during the plank phase.', 'Skipping the chest-to-floor phase, which removes the difficulty.']::text[], 'Exhale as you stand and jump.', 3, 10, null, 60, 'Drop the jump entirely if you have any joint impact concern, are new to training, or are on a hard surface with no footwear. Do not burpee rapidly into a fatigued state.'),
  ('6e27477d-f304-5079-9f2b-03c9e2338077', 'Step Jack', 'step-jack', 'A low-impact stand-in for jumping jacks. The right default when jumping is not an option, and it raises the heart rate without landing forces.', ARRAY['full_body']::body_part[], ARRAY['full_body']::muscle_group[], ARRAY['deltoids', 'calves']::muscle_group[], 'beginner'::fitness_level, 'jump'::exercise_type, 'none'::equipment, ARRAY['Stand with the feet together and the arms at the sides.', 'Step one foot out to the side while raising the opposite arm overhead.', 'Return and repeat on the other side.']::text[], ARRAY['Stay tall; the arms reach up and the feet step out.']::text[], ARRAY['Stomping rather than stepping.']::text[], 'Exhale as the arms reach up.', 3, 30, null, 45, 'No landing impact, so this is a good substitute on hard floors or with joint concerns.'),
  ('3100da88-9966-5c7e-9487-ec041b3a742f', 'High-Knee March', 'high-knee-march', 'Upright cardio that is easy to scale and puts almost no load on the wrists or back.', ARRAY['full_body', 'legs']::body_part[], ARRAY['full_body']::muscle_group[], ARRAY['quads', 'hip_flexors', 'calves']::muscle_group[], 'beginner'::fitness_level, 'locomotion'::exercise_type, 'none'::equipment, ARRAY['Stand tall and march in place, driving one knee to hip height.', 'Swing the opposite arm as you lift the knee.', 'Maintain a steady pace and breathe rhythmically.']::text[], ARRAY['Stay on the balls of the feet with a light, quick cadence.']::text[], ARRAY['Leaning back as the knee comes up.']::text[], 'Breathe in for two steps, out for two.', 3, 40, null, 30, 'Hold a wall for balance. Low impact and easy to slow down.'),
  ('d29848df-a85f-5e54-b49b-7eaafd5874b6', 'Squat Jump', 'squat-jump', 'Power work with real landing forces. Listed for completeness, but it is the one movement here that most beginners should avoid.', ARRAY['legs', 'full_body']::body_part[], ARRAY['quads']::muscle_group[], ARRAY['glutes', 'calves', 'full_body']::muscle_group[], 'advanced'::fitness_level, 'jump'::exercise_type, 'none'::equipment, ARRAY['Stand with feet shoulder width.', 'Sit back into a squat, then drive explosively upward and leave the floor.', 'Land softly, absorbing through the hips and knees.']::text[], ARRAY['Land quietly with the knees tracking over the toes.']::text[], ARRAY['Landing with straight legs.', 'Exhausting into the jump.']::text[], 'Exhale on takeoff, inhale on landing.', 3, 8, null, 90, 'Not appropriate if you have any joint, impact, or back concerns, or if you are new to training. A regular bodyweight squat trains the same muscles with far less risk.'),
  ('56e76a52-71c3-50c8-9b53-9ff7d57a8a3b', 'Shadow Boxing', 'shadow-boxing', 'Continuous low-impact conditioning that also works on coordination and pacing. The default cardio choice in a small space.', ARRAY['full_body']::body_part[], ARRAY['full_body']::muscle_group[], ARRAY['deltoids', 'abs', 'calves']::muscle_group[], 'beginner'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Stand in a staggered stance with the hands up.', 'Throw controlled straight punches while shifting the weight rhythmically.', 'Keep moving for the full interval.']::text[], ARRAY['Rotate through the hips and the rear heel.', 'Keep the chin tucked and the hands up between combinations.']::text[], ARRAY['Punching with only the arm.', 'Standing flat-footed and square to the front.']::text[], 'Exhale with every punch. Do not hold your breath.', 3, null, 60, 45, 'No impact. Keep the punches controlled — this is conditioning, not a power drill.'),
  ('5b60c596-8816-531a-82b5-99c749aaf028', 'Inchworm Walk-Out', 'inchworm-walk-out', 'Loaded posterior-chain work using body weight only. Harder on the hamstrings and back than it looks, so it should be built up gradually.', ARRAY['back', 'legs', 'core']::body_part[], ARRAY['hamstrings']::muscle_group[], ARRAY['erector_spine', 'deltoids', 'abs']::muscle_group[], 'intermediate'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Stand tall, then hinge forward and place the hands on the floor.', 'Walk the hands out to a tall plank, one hand at a time.', 'Hold the plank briefly, then walk the feet toward the hands and stand.']::text[], ARRAY['Take short steps so the hips stay relatively high.', 'The back stays flat and long as you fold.']::text[], ARRAY['Rounding the back when the hamstrings run out of length.', 'Forcing the walk-out past a tight hamstring, which rounds the spine.']::text[], 'Exhale as the hands walk out.', 3, 8, null, 60, 'Stop before the lower back rounds. Bent knees are a legitimate and preferable option to a rounded spine.'),
  ('8a6c0571-33e5-59f2-87a7-cac3f9eb01d9', 'Sprawling Lunge', 'sprawling-lunge', 'A moving, floor-to-lunge pattern that raises the heart rate while training the single-leg and upper-body positions at the same time.', ARRAY['full_body', 'legs']::body_part[], ARRAY['quads', 'glutes']::muscle_group[], ARRAY['chest', 'abs', 'full_body']::muscle_group[], 'intermediate'::fitness_level, 'locomotion'::exercise_type, 'none'::equipment, ARRAY['From a standing position, step one foot back and lower the hands to the floor inside the front foot.', 'Bring the back foot up toward the hands into a low runner’s lunge.', 'Stand up and switch legs.']::text[], ARRAY['The front heel stays down and the front shin stays near vertical.']::text[], ARRAY['Hands placed far outside the front foot.']::text[], 'Exhale as you stand up.', 3, 12, null, 60, 'Keep the hands on a mat or carpet if the floor is hard.'),
  ('d393cd7a-460a-5db8-b207-0fd914efa841', 'Cat-Cow', 'cat-cow', 'The standard spinal mobility warm-up. Cheap, safe, and effective at taking the spine through its full flexion and extension range.', ARRAY['back', 'core']::body_part[], ARRAY['erector_spine']::muscle_group[], ARRAY['abs', 'abs']::muscle_group[], 'beginner'::fitness_level, 'stretch'::exercise_type, 'none'::equipment, ARRAY['Set up on hands and knees, hands under the shoulders, knees under the hips.', 'Inhale and drop the belly, lifting the chest and tailbone (cow).', 'Exhale and round the spine, tucking the chin and drawing the navel in (cat).', 'Move slowly between the two.']::text[], ARRAY['The movement is led by the spine, segment by segment.', 'Move with the breath rather than faster than it.']::text[], ARRAY['Rushing through the range.', 'Moving only the lower back.']::text[], 'Inhale into cow, exhale into cat. The breath drives the movement.', 2, 10, null, 0, 'A comfortable range only. Stop if the neck or back is painful.'),
  ('7555926d-7f09-5e6d-a7fe-f5e59c8cd63e', 'World’s Greatest Stretch', 'world-s-greatest-stretch', 'A flowing lunge that takes the hips, hamstrings, and thoracic spine through their ranges in one sequence. Good before or after a session.', ARRAY['full_body', 'back', 'legs']::body_part[], ARRAY['glutes', 'hip_flexors']::muscle_group[], ARRAY['hamstrings', 'thoracic_spine', 'deltoids']::muscle_group[], 'beginner'::fitness_level, 'stretch'::exercise_type, 'none'::equipment, ARRAY['Step into a deep lunge with the front foot ahead of the hand.', 'Place the same-side hand on the floor inside the front foot and the other on the back thigh.', 'Rotate the chest toward the front knee, following the raised hand with your eyes.', 'Hold, then return to the lunge and switch sides.']::text[], ARRAY['The back knee rests on the floor for support.', 'Rotation comes from the mid and upper back, not from forcing the twist.']::text[], ARRAY['Rushing the rotation.', 'Letting the back knee lift.']::text[], 'Inhale to lengthen, exhale as you rotate.', 2, 6, null, 0, 'Hold the floor or a wall if the balance is not there yet.'),
  ('2e81b04b-df7f-53ed-a626-ca1869dd91bf', '90/90 Hip Switch', '90-90-hip-switch', 'Rotation for the hips in a seated position. More demanding on the hips than it looks, so ease into the range rather than forcing it.', ARRAY['legs', 'glutes']::body_part[], ARRAY['glutes', 'adductors']::muscle_group[], ARRAY['hip_flexors']::muscle_group[], 'intermediate'::fitness_level, 'stretch'::exercise_type, 'none'::equipment, ARRAY['Sit on the floor with both knees bent 90 degrees.', 'Place both hands behind you for support.', 'Rotate both knees to one side, then the other, keeping the feet planted.']::text[], ARRAY['Sit tall rather than collapsing into the hands.']::text[], ARRAY['Rushing between sides.', 'Letting the lower back round.']::text[], 'Breathe slowly and hold briefly at each end range.', 2, 10, null, 0, 'Skip this if it causes sharp pain at the hip joint. Keep the range conservative.'),
  ('3e6b0bba-404a-5bcc-a57e-d5306db2e9c9', 'Thoracic Rotation on Floor', 'thoracic-rotation-on-floor', 'Upper-back rotation and breathing position. Directly counters the effect of hours of sitting.', ARRAY['back', 'shoulders']::body_part[], ARRAY['rhomboids', 'traps']::muscle_group[], ARRAY['obliques']::muscle_group[], 'beginner'::fitness_level, 'stretch'::exercise_type, 'none'::equipment, ARRAY['Lie on your back with the arms out to the sides and the knees bent.', 'Drop both knees to one side while keeping the shoulders down.', 'Hold, then switch sides.']::text[], ARRAY['The shoulders stay heavy on the floor — the knees move, the upper back does not.']::text[], ARRAY['Lifting the shoulders to force more rotation.']::text[], 'Breathe into the side you are rotating toward.', 2, 8, null, 0, 'Gentle and pain-free. Do not force the knees to the floor.'),
  ('928f4600-643c-5c3d-99c4-f5dd4409fe3b', 'Child’s Pose to Reach', 'child-s-pose-to-reach', 'A back and shoulder stretch that also lengthens the lats — one of the few reliable ways to get a lat stretch without a bar to hang from.', ARRAY['back', 'shoulders']::body_part[], ARRAY['lats', 'traps']::muscle_group[], ARRAY['erector_spine']::muscle_group[], 'beginner'::fitness_level, 'stretch'::exercise_type, 'none'::equipment, ARRAY['Kneel and sit the hips back toward the heels.', 'Walk the hands forward and let the chest sink toward the floor.', 'Reach one arm at a time further forward, alternating sides.']::text[], ARRAY['Hips move back toward the heels rather than staying high.']::text[], ARRAY['Hips staying up, which reduces the lat stretch.']::text[], 'Breathe deeply into the lower back, which moves with each inhale.', 2, 6, null, 0, 'Rest the forehead on a folded towel or a block if the floor is hard.'),
  ('ae375470-9f0b-526b-8e46-70503f841014', 'Wall Ankle Rocks', 'wall-ankle-rocks', 'Ankle mobility to support squat depth, using a wall as a depth reference. Nothing fancy, and effective.', ARRAY['legs']::body_part[], ARRAY['calves']::muscle_group[], ARRAY['quads', 'hip_flexors']::muscle_group[], 'beginner'::fitness_level, 'stretch'::exercise_type, 'none'::equipment, ARRAY['Stand facing a wall, one foot about a fist from the wall.', 'Keep the heel down and drive the knee forward to touch the wall.', 'Rock back to a straight leg, then forward again.']::text[], ARRAY['The heel stays in contact with the floor throughout.']::text[], ARRAY['Lifting the heel to gain depth.']::text[], 'Slow, steady breathing. Hold briefly at each end.', 2, 12, null, 0, 'Reduce the range with any ankle or Achilles history.'),
  ('5b300433-48ba-57ed-8721-eba55087d0c6', 'Leg Swings', 'leg-swings', 'Dynamic hip and hamstring warm-up. A good first thing before squats or lunges, and a safe opener for stiff hips.', ARRAY['legs', 'glutes']::body_part[], ARRAY['hip_flexors', 'hamstrings']::muscle_group[], ARRAY['glutes', 'calves']::muscle_group[], 'beginner'::fitness_level, 'stretch'::exercise_type, 'none'::equipment, ARRAY['Stand tall holding a wall for balance.', 'Swing one leg forward and back under control.', 'Complete the set, then switch legs.']::text[], ARRAY['The movement comes from the hip; the knee stays mostly straight.']::text[], ARRAY['Swinging with the torso, turning it into a windmill.']::text[], 'Breathe steadily; do not hold your breath at the end range.', 2, 15, null, 0, 'Keep the range easy. Swinging is a warm-up, not a stretch contest.'),
  ('ae8194bb-7a3e-5113-8800-0229b7b028e4', 'Deep Squat Hold', 'deep-squat-hold', 'An active, loaded squat position that teaches the ankles, hips, and pelvis to be comfortable low. Uncomfortable at first — that is normal, and range improves.', ARRAY['legs', 'glutes']::body_part[], ARRAY['quads', 'glutes']::muscle_group[], ARRAY['abs', 'calves', 'adductors']::muscle_group[], 'intermediate'::fitness_level, 'bodyweight_squat'::exercise_type, 'none'::equipment, ARRAY['Stand with the feet a little wider than the shoulders, toes turned out.', 'Sink into a deep squat, keeping the heels down.', 'Place the elbows inside the knees and use the arms to drive them apart.', 'Hold the position.']::text[], ARRAY['The whole foot stays in contact with the floor.', 'The lower back stays long; do not round to go lower.']::text[], ARRAY['Heels lifting.', 'Rounding the lower back.', 'Leaning too far forward.']::text[], 'Breathe continuously during the hold. Do not hold your breath.', 3, null, 30, 45, 'Stay on the edge of your comfortable range. Coming up onto the toes to finish a deep hold defeats the purpose, and a rounded lower back is not an acceptable trade.'),
  ('d913e999-edee-5ccb-a7dd-afbca4afd47b', 'Wall Push-Up', 'wall-push-up', 'The lowest-load press in the library, and a genuine starting point rather than a lesser version. A wall leaves the chest working at a steep upward angle, so the arms press a manageable weight.', ARRAY['chest', 'shoulders', 'arms']::body_part[], ARRAY['chest']::muscle_group[], ARRAY['triceps', 'deltoids']::muscle_group[], 'beginner'::fitness_level, 'push_up'::exercise_type, 'none'::equipment, ARRAY['Stand facing a wall, feet close to it, and place both palms flat on the wall at chest height.', 'Keep the body in one straight line, inclined upward toward the wall.', 'Bend the elbows to bring the chest toward the wall.', 'Press away until the arms are straight, then repeat with control.']::text[], ARRAY['Glides are fine here; the body angle is what sets the load, not speed.', 'Hands at chest height, not waist height, or the arms do the work instead of the chest.']::text[], ARRAY['Letting the hips drift toward the wall so the body breaks its straight line.']::text[], 'Inhale toward the wall, exhale as you press away.', 3, 15, null, 45, 'Ideal first press for anyone returning to exercise after a break. Nothing here loads a joint heavily, so move on once it feels easy rather than staying here.'),
  ('44e5d5ae-3609-59fd-b761-b91b6b9b245e', 'Knee Push-Up', 'knee-push-up', 'A floor press with the knees down. It reduces the lever arm compared to a full push-up, which makes it a reasonable bridge once a wall press is comfortable.', ARRAY['chest', 'shoulders', 'arms']::body_part[], ARRAY['chest']::muscle_group[], ARRAY['triceps', 'deltoids']::muscle_group[], 'beginner'::fitness_level, 'push_up'::exercise_type, 'none'::equipment, ARRAY['Kneel on a mat and place the hands on the floor slightly wider than the shoulders.', 'Extend one leg back at a time until only the knees and hands support the body.', 'Keep the hips level with the shoulders and lower the chest between the hands.', 'Press the floor away to a straight arm, then return the knees down before resting.']::text[], ARRAY['Squeeze the glutes on the way down so the lower back does not arch.', 'Only the knees rest between reps, so the torso stays under tension.']::text[], ARRAY['Hips sagging toward the floor, which pulls the load off the chest and onto the lower back.']::text[], 'Inhale down, exhale up.', 3, 12, null, 60, 'A sagging hip is the only way to injure this. If the hips drop, go back to a wall or incline push-up rather than pressing through the lower back.'),
  ('a28f5b91-dd15-5781-a728-2bbd6b9aa083', 'Wide Push-Up', 'wide-push-up', 'A push-up with the hands spread wider than the shoulders. It shifts emphasis toward the chest and the outer shoulder, and shortens the arc the chest travels.', ARRAY['chest', 'shoulders', 'arms']::body_part[], ARRAY['chest']::muscle_group[], ARRAY['deltoids', 'triceps']::muscle_group[], 'beginner'::fitness_level, 'push_up'::exercise_type, 'none'::equipment, ARRAY['Place the hands well outside shoulder width, fingers spread and turned slightly out.', 'Walk the feet back to a straight line from head to heels.', 'Lower the chest between the hands with the elbows tracking outward at a shallow angle.', 'Press the floor away to a straight arm.']::text[], ARRAY['Hands wider than the shoulders, not merely shoulder width.', 'Keep the glutes engaged so the hips do not sag between the shoulders.']::text[], ARRAY['Letting the hands creep inward until it quietly becomes a normal push-up.', 'Flaring the elbows straight out to shoulder height, which stresses the front of the shoulder.']::text[], 'Inhale as you lower, exhale as you press up.', 3, 10, null, 60, 'Stop if the front of the shoulder pinches at the bottom. Bring the hands in to shoulder width rather than pushing through the joint.'),
  ('05692042-9d43-53a3-a28e-1e0d70233e11', 'Diamond Push-Up', 'diamond-push-up', 'A push-up with the hands close together beneath the chest, which loads the triceps more heavily than any other press in the library.', ARRAY['chest', 'shoulders', 'arms']::body_part[], ARRAY['triceps']::muscle_group[], ARRAY['chest', 'deltoids']::muscle_group[], 'intermediate'::fitness_level, 'push_up'::exercise_type, 'none'::equipment, ARRAY['Place the hands together on the floor beneath the sternum, thumbs and index fingers touching to form a diamond.', 'Walk the feet back to a straight line.', 'Keeping the elbows close to the body, lower until the chest approaches the hands.', 'Press the floor away, keeping the arms close to the ribs the whole way.']::text[], ARRAY['Elbows stay within a hand-width of the torso, not flared out.', 'Shoulders stay packed down away from the ears throughout.']::text[], ARRAY['Letting the elbows drift out, which turns the exercise back into a normal push-up.', 'Hips piking up because the chest is too close to the floor.']::text[], 'Inhale down, exhale up.', 3, 8, null, 75, 'Triceps loading is high, so the wrist and elbow take more. Anyone with wrist pain should use a regular push-up instead.'),
  ('16a75b36-bb2b-58a9-a81e-4f30c7ca11c0', 'Decline Push-Up', 'decline-push-up', 'A push-up with the feet elevated on a chair or bed, raising the head above the feet. The steeper angle increases the load on the chest and shoulders.', ARRAY['chest', 'shoulders', 'arms']::body_part[], ARRAY['chest']::muscle_group[], ARRAY['deltoids', 'triceps']::muscle_group[], 'intermediate'::fitness_level, 'push_up'::exercise_type, 'none'::equipment, ARRAY['Stand with the feet behind you and place the toes on a stable chair, bed edge, or step.', 'Walk the hands forward until the body forms a straight, downward-sloping line.', 'Lower the chest toward the floor between the hands.', 'Press the floor away to a straight arm.']::text[], ARRAY['The body must stay in one line; the steeper the better once the position is stable.', 'Push away from the hands, not up through the shoulders.']::text[], ARRAY['Letting the hips sag, which at this angle shifts most of the load into the lower back.', 'Using a surface that slides under the feet.']::text[], 'Inhale down, exhale up.', 3, 8, null, 75, 'Confirm the elevated surface will not slide before you begin. Keep the hips locked; this position makes a sagging back easier and more punishing than in a level push-up.'),
  ('a33c6616-65f7-5499-8043-2a52449ebedd', 'Push-Up Plus', 'push-up-plus', 'A push-up that ends with a deliberate scapular protraction, pushing the floor away and rounding the upper back at the top. It adds a small amount of upper-back work to the press.', ARRAY['chest', 'shoulders', 'back', 'arms']::body_part[], ARRAY['chest']::muscle_group[], ARRAY['triceps', 'rhomboids', 'deltoids']::muscle_group[], 'beginner'::fitness_level, 'push_up'::exercise_type, 'none'::equipment, ARRAY['Set up in a standard push-up position with the body in a straight line.', 'Lower the chest to the floor under control.', 'Press up to a straight arm, then deliberately push the floor away and round the upper back.', 'Let the shoulder blades spread back together, then return to neutral and repeat.']::text[], ARRAY['The extra movement happens at the very top, only after the arm is straight.', 'Let the upper back round. Rounding is the point of the exercise.']::text[], ARRAY['Rounding the lower back instead of the upper back.', 'Adding a shoulder shrug on top of the press.']::text[], 'Exhale as you press up and push the floor away. Inhale down.', 3, 10, null, 60, 'The final protraction can pinch the shoulder if it is forced. Keep the range of motion small and stop if the front of the shoulder hurts.'),
  ('57d1cbec-4dd2-5c06-81bd-15eaea6f6e0e', 'Bird Dog', 'bird-dog', 'A quadruped control drill that trains the spine to stay still while the limbs move. It is a stability staple and the gentlest way to learn to load the core without holding a position.', ARRAY['core', 'back', 'full_body']::body_part[], ARRAY['abs']::muscle_group[], ARRAY['erector_spine', 'glutes', 'rhomboids']::muscle_group[], 'beginner'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Set up on hands and knees with the wrists under the shoulders and the knees under the hips.', 'Brace the core so the lower back holds a neutral position.', 'Extend one arm forward and the opposite leg back until both are level with the torso.', 'Hold for two seconds without letting the hips rotate, then return and switch sides.']::text[], ARRAY['Reach long rather than high, so the hip stays level with the shoulder.', 'Keep the lower back completely still; any arch means the range is too long.']::text[], ARRAY['Rotating the hips open to get the leg higher, which removes the anti-rotation demand.', 'Lifting the leg so high the lower back arches.']::text[], 'Exhale as you extend, inhale as you return. Do not hold your breath during the two-second hold.', 3, 8, null, 45, 'The flat back is the whole exercise. If the lower back rounds or arches, lift the leg less. Stop if you feel anything sharp in the lower back.'),
  ('da225bef-82e0-5d81-b298-6fcd14374343', 'Side-Lying Adductor Raise', 'side-lying-adductor-raise', 'An isolation hold for the inner thigh, done lying on your side with the top leg propped forward on a chair or the floor. It is the only beginner-friendly way to load the adductors without equipment.', ARRAY['legs']::body_part[], ARRAY['adductors']::muscle_group[], ARRAY['glutes']::muscle_group[], 'beginner'::fitness_level, 'stretch'::exercise_type, 'none'::equipment, ARRAY['Lie on your side with the top leg crossed over and planted in front of you on a chair or the floor.', 'Extend the bottom leg along the floor with the foot flexed.', 'Lift the bottom leg a few centimetres and hold for the set time, keeping the knee straight.', 'Lower under control and repeat on the same side, then switch.']::text[], ARRAY['Keep the knee of the lifting leg straight; any bend shifts the work to the hip flexor.', 'Point the toes of the lifting foot toward the shin to keep the inner thigh engaged.']::text[], ARRAY['Bending the knee to make it easier, which turns it into a hip-flexor exercise.', 'Letting the bottom knee rest on the floor between reps and resting.']::text[], 'Breathe steadily throughout the hold. Do not hold your breath.', 3, null, 20, 45, 'The inner thigh has little padding; use a mat. If you feel a muscle cramp, stop and stretch gently before continuing.'),
  ('b7c8290c-7d93-5365-9b18-f1d9c7938ccf', 'Copenhagen Plank', 'copenhagen-plank', 'A side plank where the top leg is anchored to a chair or bench, forcing the adductors of the bottom leg to hold the hips high. It is the gold-standard bodyweight adductor exercise and is clearly intermediate.', ARRAY['legs', 'core']::body_part[], ARRAY['adductors']::muscle_group[], ARRAY['obliques', 'glutes']::muscle_group[], 'intermediate'::fitness_level, 'plank'::exercise_type, 'none'::equipment, ARRAY['Set a chair or bench at hip height. Place the top leg on it at the knee or shin.', 'Get into a side plank on the forearm, with the bottom leg hanging free.', 'Drive the bottom hip up until the body is in a straight line.', 'Hold for the set time without letting the hips drop or rotate.']::text[], ARRAY['Keep the elbow directly under the shoulder to protect it.', 'Imagine pulling the bottom knee up to meet the top leg; that is where the work lives.']::text[], ARRAY['Letting the hips sag toward the floor, which removes the adductor load.', 'Rotating the chest open so the work shifts to the obliques.']::text[], 'Breathe steadily throughout the hold. A shallow breath is fine if a full breath makes you lose the position.', 3, null, 20, 60, 'The adductors and obliques both cramp easily under load. Stop and stretch if the inner thigh cramps.'),
  ('5d5acde6-0187-5a9e-b1bb-ffc4057efa9e', 'Prone Cobra', 'prone-cobra', 'A gentle back extension where the chest and arms lift off the floor without using the hands to push. It teaches the lower back to work without the arms and is the safest entry point.', ARRAY['back']::body_part[], ARRAY['erector_spine']::muscle_group[], ARRAY['glutes', 'rhomboids']::muscle_group[], 'beginner'::fitness_level, 'stretch'::exercise_type, 'none'::equipment, ARRAY['Lie face down with the hands at the sides, palms down, and the forehead on the floor.', 'Lift the chest, arms, and forehead off the floor by squeezing the lower back and glutes.', 'Hold the top for a breath without using the hands to push.', 'Lower under control and repeat.']::text[], ARRAY['Reach long rather than high; think length, not height.', 'Keep the neck neutral by looking down at the floor, not forward.']::text[], ARRAY['Using the hands to push the chest up, which turns it into a push-up.', 'Craning the neck up to get the chest higher, which loads the neck instead.']::text[], 'Exhale as you lift, inhale as you lower.', 3, 12, null, 45, 'The neck should stay in line with the spine; craning the head up to get the chest higher loads the neck instead. Stop if the lower back pinches.'),
  ('eb9ae919-89a3-5f8a-bf23-3677ff739dca', 'Reverse Hyperextension', 'reverse-hyperextension', 'A floor-based hip hinge where the hips lift off the floor by extending the lower back and glutes. It is the honest floor replacement for a loaded back extension and sits clearly at intermediate.', ARRAY['back', 'glutes']::body_part[], ARRAY['erector_spine', 'glutes']::muscle_group[], ARRAY['hamstrings']::muscle_group[], 'intermediate'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Lie face down with the hips at the edge of a bench or sofa.', 'Hang the legs off the edge with the toes touching the floor.', 'Grip the sides of the bench and hinge the hips up off the edge by squeezing the lower back and glutes.', 'Lower under control and repeat.']::text[], ARRAY['Keep the knees slightly bent; straight knees transfer the work to the hamstrings.', 'The lift should stop when the hips are level with the bench; do not arch beyond that.']::text[], ARRAY['Lifting with a jerking motion, which can strain the lower back.', 'Arching the neck to get the hips higher, which loads the neck instead.']::text[], 'Exhale as you lift, inhale as you lower.', 3, 10, null, 60, 'The hips at the edge of the bench are a leverage point; if you feel a pinch, stop and adjust the position. A slow, controlled motion is the only safe way to do this.'),
  ('17ba4f10-e542-57da-9dbe-ed592f5a7fa1', 'Single-Leg Calf Raise', 'single-leg-calf-raise', 'A unilateral calf raise that doubles the load on each leg and reveals any left–right differences. It is the honest intermediate progression from the two-leg version.', ARRAY['legs']::body_part[], ARRAY['calves']::muscle_group[], ARRAY['glutes']::muscle_group[], 'intermediate'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Stand on the edge of a step with one foot, using a wall for light balance if needed.', 'Rise up onto the toes of the standing foot as high as possible.', 'Lower under control until the heel drops below the step level.', 'Complete all reps on one side, then switch.']::text[], ARRAY['Keep the knee of the working leg straight; any bend shifts the work to the soleus.', 'Imagine pressing the big toe into the step to keep the foot from rolling out.']::text[], ARRAY['Bending the knee to make it easier, which turns it into a two-muscle exercise.', 'Using the free leg to push off the floor, which hides a strength difference.']::text[], 'Exhale as you rise, inhale as you lower.', 3, 12, null, 45, 'The Achilles tendon is the only thing between you and the floor; do not bounce at the bottom. A step is the minimum equipment; a staircase works.'),
  ('5a728c3c-c46a-50b0-9a45-c07719b4862b', 'Tempo Calf Raise', 'tempo-calf-raise', 'A calf raise done with a four-second lowering phase to load the tendon and muscle through a longer period of tension. It is the honest advanced progression when single-leg raises get easy.', ARRAY['legs']::body_part[], ARRAY['calves']::muscle_group[], '{}'::muscle_group[], 'advanced'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Stand on the edge of a step on two feet.', 'Rise up onto the toes in one second.', 'Take four full seconds to lower the heels below the step level.', 'Rise again without pausing at the top or the bottom.']::text[], ARRAY['The four-second countdown should feel like an eternity; that is the point.', 'Keep the knees still; any bend at the knee unloads the calves.']::text[], ARRAY['Dropping the heels quickly, which removes the load on the tendon.', 'Pausing at the top, which turns it into two separate exercises.']::text[], 'Breathe normally; a short hold at the top is fine, but the four-second lower should not interrupt breathing.', 3, 10, null, 75, 'The eccentric load is high. If you have any Achilles pain, do the two-leg version less aggressively until it clears up.'),
  ('36f64d7c-a6fb-5978-b2a2-495ec26692ee', 'Windshield Wipers', 'windshield-wipers', 'A supine core exercise where the legs sweep from side to side like wipers, loading the obliques through a rotational arc. It is the gentlest floor entry for the obliques.', ARRAY['core']::body_part[], ARRAY['obliques']::muscle_group[], ARRAY['abs']::muscle_group[], 'beginner'::fitness_level, 'stretch'::exercise_type, 'none'::equipment, ARRAY['Lie on your back with the arms out to the sides and the knees bent at 90 degrees.', 'Keep the knees together and let them drop slowly to one side.', 'Pause at the bottom, then pull the knees back up to the start using the obliques.', 'Lower to the other side under control.']::text[], ARRAY['Keep the shoulders welded to the floor; if a shoulder lifts, the range is too wide.', 'Think of the knees as a single block, not as two legs swinging independently.']::text[], ARRAY['Letting the shoulders lift off the floor, which turns it into a spinal twist.', 'Letting the knees drop with gravity, which removes the obliques from the lowering phase.']::text[], 'Exhale as you pull the knees up, inhale as you lower them.', 3, 10, null, 45, 'Keep the movement slow. This is a controlled arc, not a spinal twist. Stop if the lower back clicks or you feel a deep pinch.'),
  ('f3fafc2f-b7b4-58ac-8a5f-32e50cb003c9', 'Side Plank with Leg Lift', 'side-plank-with-leg-lift', 'A side plank with the top leg raised during the hold to add a glute load and force the obliques to work harder against the extra lever. It is a straight upgrade from the side plank.', ARRAY['core', 'glutes']::body_part[], ARRAY['obliques', 'glutes']::muscle_group[], ARRAY['abs']::muscle_group[], 'intermediate'::fitness_level, 'plank'::exercise_type, 'none'::equipment, ARRAY['Get into a side plank on the forearm.', 'Raise the top leg a few centimetres and hold it there.', 'Hold the position for the set time without letting the hips drop.', 'Switch sides after the set.']::text[], ARRAY['Keep the elbow directly under the shoulder to protect it.', 'Imagine holding a coin between the top inner thighs to keep the hips high.']::text[], ARRAY['Letting the hips sag toward the floor, which unloads the obliques.', 'Lifting the top leg so high the hip flexor takes over.']::text[], 'Breathe steadily throughout the hold. A shallow breath is fine if a full breath makes you lose the position.', 3, null, 25, 60, 'The shoulder takes more load than in a regular side plank. Stop if the shoulder feels strained.'),
  ('b5d828f5-abb9-58e1-b248-44aa71a6f35b', 'Single-Leg Glute Bridge March', 'single-leg-glute-bridge-march', 'A glute bridge with the top position held while the feet alternate marching. It adds the hamstrings to the glute load by creating a longer moment arm and is the honest intermediate step.', ARRAY['legs', 'glutes']::body_part[], ARRAY['hamstrings', 'glutes']::muscle_group[], ARRAY['erector_spine']::muscle_group[], 'intermediate'::fitness_level, 'bridge'::exercise_type, 'none'::equipment, ARRAY['Set up as for a regular glute bridge and lift the hips to the top position.', 'Keep the hips level and lift one foot off the floor, straightening the knee only slightly.', 'Place it back down and lift the other foot, alternating for the set count.', 'Keep the hips at full height throughout; do not let them drop between reps.']::text[], ARRAY['Imagine a tray of drinks on the hips; level hips are the whole exercise.', 'Press the standing heel into the floor to keep the hamstring engaged.']::text[], ARRAY['Letting the hips drop as the feet move, which removes the isometric load.', 'Straightening the lifted knee fully, which turns it into a quad exercise.']::text[], 'Breathe steadily throughout the march.', 3, 8, null, 60, 'The hamstring cramp is a sign you are lifting the leg too fast. Slow the march down if that happens.'),
  ('4d6ae723-946e-567d-a65a-f4b535f33880', 'Nordic Curl Eccentric', 'nordic-curl-eccentric', 'A kneeling hamstring exercise where you use your arms to catch yourself as you lower. It is the only bodyweight exercise that loads the hamstrings through a full range of motion and is clearly advanced.', ARRAY['legs']::body_part[], ARRAY['hamstrings']::muscle_group[], ARRAY['glutes', 'calves']::muscle_group[], 'advanced'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Kneel on a padded surface and anchor your ankles under a sofa or have a partner hold them.', 'Cross your arms in front of the chest or place the hands under the shoulders in a push-up position.', 'Lower the torso down with only the hamstrings, catching yourself with the arms at the bottom.', 'Push up with the arms to return to the kneeling start; the hamstrings only work on the way down.']::text[], ARRAY['Keep the hips extended; any hinge at the hips removes the hamstring load.', 'Imagine pulling the body down with the hamstrings, not just resisting gravity.']::text[], ARRAY['Bending at the hips to touch the floor sooner, which hides the hamstring weakness.', 'Using the arms to push up on the way up, which removes the concentric work entirely.']::text[], 'Inhale as you lower, exhale as you push up.', 3, 5, null, 90, 'This is a high-load eccentric. If you have any hamstring history, start with one or two reps and build up slowly. A partner is a safer anchor than a sofa.'),
  ('a214a3ef-fa25-5a28-90b8-28efba759a1a', 'Standing Knee Drive', 'standing-knee-drive', 'A standing hip-flexor drill that mimics the top of a sprint stride. It loads the hip flexors without lying down and transfers better to walking and climbing than a floor exercise.', ARRAY['legs']::body_part[], ARRAY['hip_flexors']::muscle_group[], ARRAY['glutes']::muscle_group[], 'beginner'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Stand tall with the feet hip-width apart.', 'Drive one knee up toward the chest as high as the hip allows without leaning back.', 'Lower under control and repeat with the same leg, then switch.']::text[], ARRAY['Keep the standing leg straight and the torso upright; lean back only if the knee rises above hip height.', 'Imagine driving the knee into a wall in front of you.']::text[], ARRAY['Leaning back to get the knee higher, which transfers the work to the lower back.', 'Swinging the leg up, which uses momentum instead of the hip flexors.']::text[], 'Exhale as you drive the knee up, inhale as you lower.', 3, 12, null, 45, 'A wall for light balance is fine and does not reduce the training effect. Stop if you feel a pinch in the hip.'),
  ('c1434daf-280b-5ebc-89be-f20b8ff7eb5c', 'Mountain Climber (Slow)', 'mountain-climber-slow', 'A mountain climber done at half speed with a pause at the top of each drive. It removes the cardio crossover and isolates the hip flexors, which is what most people actually use the exercise for.', ARRAY['core', 'legs']::body_part[], ARRAY['hip_flexors', 'abs']::muscle_group[], ARRAY['abs']::muscle_group[], 'intermediate'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Set up in a push-up position.', 'Drive one knee toward the chest and hold it for two seconds.', 'Return to the start and repeat with the other leg at the same slow tempo.']::text[], ARRAY['Keep the hips still; only the legs should move.', 'Drive the knee to the nose, not just the chest.']::text[], ARRAY['Letting the hips bounce up and down, which introduces the shoulders uninvited.', 'Rushing the tempo, which hides hip-flexor weakness.']::text[], 'Exhale as you drive, inhale as you return.', 3, 10, null, 45, 'The shoulders bear the full body for the whole set. Stop if the wrist or shoulder feels strained.'),
  ('817c521f-4fa6-5b87-98de-6769b4d0fd84', 'Wall Walk', 'wall-walk', 'A handstand progression where you walk your feet up the wall into a tall plank. It loads the shoulders and chest with bodyweight at a manageable angle and is the clear intermediate step from the pike push-up.', ARRAY['shoulders', 'chest']::body_part[], ARRAY['deltoids', 'triceps']::muscle_group[], ARRAY['abs']::muscle_group[], 'intermediate'::fitness_level, 'push_up'::exercise_type, 'none'::equipment, ARRAY['Start in a plank with the feet against the base of a wall.', 'Walk the feet up the wall as you simultaneously walk the hands toward the wall.', 'Stop when the hips are over the hands or at the maximum comfortable height.', 'Walk back down under control.']::text[], ARRAY['Move the hands and feet together; one without the other leaves the hips behind.', 'Keep the elbows locked; a bent elbow unloads the shoulder.']::text[], ARRAY['Walking the hands in without the feet, which leaves the hips too far back.', 'Letting the lower back arch, which transfers the load to the lower back.']::text[], 'Breathe steadily; do not hold your breath at the top.', 3, 4, null, 90, 'The wall is your safety net. Face it the whole time so the wall is behind you, not in front.'),
  ('b3d64275-10b9-51f2-8b8a-c379147fc7c1', 'Handstand Hold (Wall)', 'handstand-hold-wall', 'A static wall-supported handstand that loads the shoulders isometrically at full bodyweight. It is the honest advanced progression and requires the wall walk as a prerequisite.', ARRAY['shoulders']::body_part[], ARRAY['deltoids']::muscle_group[], ARRAY['triceps', 'abs']::muscle_group[], 'advanced'::fitness_level, 'plank'::exercise_type, 'none'::equipment, ARRAY['Start in a wall-walk finish position, as close to the wall as comfortable.', 'Lift one foot off the wall to find the balance point.', 'Hold for the set time or until the balance fails.', 'Bring the foot back to the wall, rest, and descend with the walk-down.']::text[], ARRAY['Press the floor away to keep the shoulders shrugged up toward the ears.', 'Look at the wall, not the floor, to keep the neck neutral.']::text[], ARRAY['Letting the lower back arch into a banana shape, which loads the lower back.', 'Holding the breath, which fatigues the shoulders faster without training them.']::text[], 'Breathe steadily throughout the hold.', 3, null, 30, 90, 'The shoulder and wrist are the only things between you and the floor. Do not attempt this cold.'),
  ('57ff8061-deb6-59d2-888f-729e5a32aa20', 'Doorway Row (Wide Grip)', 'doorway-row-wide-grip', 'A horizontal row done in a doorway with a wider grip to bias the lats. It is the safest intermediate progression from the inverted row and requires only a doorway.', ARRAY['back']::body_part[], ARRAY['lats']::muscle_group[], ARRAY['rhomboids', 'biceps']::muscle_group[], 'intermediate'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Stand in a doorway with the arms at shoulder height, gripping the frame with a wide grip.', 'Walk the feet forward until the body is at a comfortable incline.', 'Pull the chest toward the frame until it touches.', 'Lower under control and repeat.']::text[], ARRAY['Think of pulling the chest to the frame, not the chin.', 'Keep the elbows slightly lower than shoulder height to load the lats, not the traps.']::text[], ARRAY['Pulling with the arms only, which removes the back from the exercise.', 'Letting the hips sag forward, which makes the row easier instead of harder.']::text[], 'Exhale as you pull, inhale as you lower.', 3, 10, null, 60, 'The doorway frame is the only anchor. Test it with a gentle tug before you commit your bodyweight to it.'),
  ('c71950f7-e177-599e-9e6a-1d8beaef05ad', 'Prone Snow Angel', 'prone-snow-angel', 'A floor drill where the arms sweep overhead and back like a snow angel while lying face down. It loads the lats and lower traps isometrically and is a finishing drill for the back day.', ARRAY['back']::body_part[], ARRAY['lats', 'erector_spine']::muscle_group[], ARRAY['rhomboids']::muscle_group[], 'beginner'::fitness_level, 'stretch'::exercise_type, 'none'::equipment, ARRAY['Lie face down with the arms at the sides and the forehead on the floor.', 'Sweep the arms overhead in a wide arc until the thumbs touch above the head.', 'Sweep back down under control to the start.']::text[], ARRAY['Keep the arms straight; any bend unloads the lats.', 'Keep the chest on the floor; a lift transfers the work to the lower back.']::text[], ARRAY['Letting the arms bend, which turns it into a shoulder exercise.', 'Lifting the chest, which hides a tight thoracic spine.']::text[], 'Breathe steadily throughout the sweep.', 2, 10, null, 45, 'A hard floor makes this uncomfortable; use a mat. Stop if the lower back feels a deep ache that does not ease when you stop.'),
  ('4748a180-7481-53a4-a105-59b6fc306447', 'Decline Pike Push-Up', 'decline-pike-push-up', 'A pike push-up with the feet elevated to increase the load on the shoulders. It is the final bodyweight step before a handstand push-up and is the honest advanced progression.', ARRAY['shoulders', 'chest']::body_part[], ARRAY['deltoids', 'triceps']::muscle_group[], '{}'::muscle_group[], 'advanced'::fitness_level, 'push_up'::exercise_type, 'none'::equipment, ARRAY['Set up in a pike position with the feet on a chair or bench.', 'Lower the head toward the floor by bending the elbows.', 'Press up to a straight arm.']::text[], ARRAY['Keep the hips high; a sagging hip hides shoulder weakness.', 'Think of pressing the floor away to keep the shoulders shrugged up.']::text[], ARRAY['Letting the hips drop toward the floor, which turns it into an incline push-up.', 'Letting the lower back arch, which transfers load to the lower back.']::text[], 'Exhale as you press up, inhale as you lower.', 3, 8, null, 75, 'The head is closer to the floor than in a regular push-up. Keep the neck neutral and look at the floor to keep it aligned.'),
  ('0f54efe3-8cf9-560b-a905-b212404dbeda', 'Suitcase Carry March', 'suitcase-carry-march', 'A marching drill with a heavy water bottle in one hand to load the obliques on the opposite side. It is the honest advanced progression the catalog previously lacked.', ARRAY['core', 'legs']::body_part[], ARRAY['obliques']::muscle_group[], ARRAY['abs', 'glutes']::muscle_group[], 'advanced'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Hold a heavy water bottle in one hand at the side.', 'March in place with high knees for the set time.', 'Keep the shoulders level; do not lean away from the weight.', 'Switch hands after the set.']::text[], ARRAY['Level shoulders are the whole exercise; any lean is a failure.', 'Drive the knees high to keep the hip flexors busy, but let the obliques do the work.']::text[], ARRAY['Leaning away from the weight, which removes the anti-rotation demand.', 'Letting the hips rotate, which transfers the work to the lower back.']::text[], 'Breathe steadily throughout the march.', 3, null, 30, 60, 'The bottle is the only weight. Test the grip before you start; a slipping bottle is a tripping hazard.'),
  ('e427bd58-7f76-528a-9202-d51de112461b', 'L-Sit Progression', 'l-sit-progression', 'A seated compression hold where you press the floor away to lift the hips. It is the final bodyweight step for the hip flexors and is a clear advanced entry.', ARRAY['core', 'legs']::body_part[], ARRAY['hip_flexors', 'abs']::muscle_group[], ARRAY['triceps', 'deltoids']::muscle_group[], 'advanced'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Sit on the floor with the legs extended and the hands flat by the hips.', 'Press the floor away to lift the hips and legs as high as the hip flexors allow.', 'Hold for the set time or until the hips start to drop.', 'Lower under control and rest.']::text[], ARRAY['Keep the knees locked; a bent knee unloads the hip flexors.', 'Think of pressing the floor away with the hands, not leaning back.']::text[], ARRAY['Bending the knees to make it easier, which turns it into a triceps exercise.', 'Leaning back, which transfers the work to the lower back.']::text[], 'Breathe steadily; do not hold your breath.', 3, null, 15, 75, 'The hip flexors are the only thing keeping you up. Stop if you feel a cramp; a cramp is a sign you have reached your current limit.'),
  ('bec8b145-eb9d-5255-a2f3-22654b9f9ad7', 'Single-Leg Nordic Curl Eccentric', 'single-leg-nordic-curl-eccentric', 'The one-leg version of the Nordic curl. It doubles the load and is the honest final step for the hamstrings in a bodyweight catalog.', ARRAY['legs']::body_part[], ARRAY['hamstrings']::muscle_group[], ARRAY['glutes']::muscle_group[], 'advanced'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Set up as for the Nordic curl eccentric but with one ankle anchored.', 'Lower the torso down with only that leg, catching yourself with the arms at the bottom.', 'Push up with the arms to return.']::text[], ARRAY['Keep the hips extended; any hinge at the hips unloads the hamstring.', 'The free leg should stay still; a swing uses momentum.']::text[], ARRAY['Letting the hips hinge, which hides the hamstring weakness.', 'Using the arms to push up, which removes the concentric work entirely.']::text[], 'Inhale as you lower, exhale as you push up.', 3, 3, null, 120, 'This is a very high-load eccentric. Do it only if the two-leg version feels easy, and start with one rep. A partner is the only safe anchor.'),
  ('1f0e253a-4fbd-5957-8595-5d6c705c5144', 'Copenhagen Plank (Full)', 'copenhagen-plank-full', 'A full Copenhagen plank with the arm extended. It is the honest advanced step and the final entry for the adductors.', ARRAY['legs', 'core']::body_part[], ARRAY['adductors', 'obliques']::muscle_group[], ARRAY['glutes']::muscle_group[], 'advanced'::fitness_level, 'plank'::exercise_type, 'none'::equipment, ARRAY['Set up as for the intermediate Copenhagen plank but with the hand on the floor, arm straight.', 'Hold for the set time without letting the hips drop.']::text[], ARRAY['Keep the hips high; a sagging hip removes the adductor load.', 'Press the floor away with the bottom arm to keep the shoulder stable.']::text[], ARRAY['Letting the hips sag, which unloads the adductors.', 'Bending the bottom arm, which unloads the shoulder.']::text[], 'Breathe steadily throughout the hold.', 3, null, 20, 90, 'The shoulder is under full bodyweight. Stop if you feel a pinch. Warm the shoulder and wrist before this.'),
  ('fd32ef6a-73f7-5b30-9a7a-0947f6203b20', 'Plyometric Squat Jump', 'plyometric-squat-jump', 'An explosive squat jump that develops reactive strength and rate of force development. It is the honest power progression beyond bent-knee strength work.', ARRAY['legs', 'full_body']::body_part[], ARRAY['quads', 'glutes']::muscle_group[], ARRAY['calves', 'hamstrings']::muscle_group[], 'advanced'::fitness_level, 'jump'::exercise_type, 'none'::equipment, ARRAY['Drop into a squat, then explode up as high as possible.', 'Land softly on the balls of the feet, immediately sinking into the next squat.', 'Minimise ground contact time; keep the torso upright.', 'Reset completely before the next rep.']::text[], ARRAY['Land like a cat, not a sack of potatoes.', 'Reset fully between reps; a rhythmic bounce wastes energy and shocks the knees.']::text[], ARRAY['Landing stiff on straight knees, which shocks the joints.', 'Bouncing without a reset, which turns it into cardio instead of power training.']::text[], 'Inhale on the way down, exhale sharply as you jump.', 3, 6, null, 90, 'The knees must track over the toes. The Achilles absorbs the landing; if you feel a sharp pain there, stop and check the tendon before continuing.'),
  ('f1bf06df-e856-5b83-942b-f81b2d0a5d94', 'Archer Push-Up', 'archer-push-up', 'A wide push-up where one arm takes most of the load while the other arm extends to the side. It is the final bodyweight step before one-arm push-up work.', ARRAY['chest', 'shoulders']::body_part[], ARRAY['chest', 'triceps']::muscle_group[], ARRAY['deltoids', 'abs']::muscle_group[], 'advanced'::fitness_level, 'push_up'::exercise_type, 'none'::equipment, ARRAY['Set up in a wide-arm push-up position.', 'Lower to one side, keeping the other arm straight and sliding along the floor.', 'Press up with the working arm, keeping the assisting arm extended.', 'Alternate sides with control.']::text[], ARRAY['The assisting arm only balances; the working arm does the press.', 'Keep the elbow of the working arm close to the ribs to protect the shoulder.']::text[], ARRAY['Letting the assisting arm bear too much weight, which halves the training effect.', 'Letting the hips rotate, which reduces the chest engagement.']::text[], 'Exhale as you press, inhale as you lower.', 3, 6, null, 90, 'This is shoulder-intensive. Never do it cold, and never force the assist arm into a painful range.'),
  ('6d39b574-cf82-5895-8b7a-3c0411bd3618', 'Single-Leg Box Squat', 'single-leg-box-squat', 'A squat down to a chair on one leg that teaches control through a full unilateral range. The box removes the fear factor while keeping the strength demand real.', ARRAY['legs', 'glutes']::body_part[], ARRAY['quads', 'glutes']::muscle_group[], ARRAY['hamstrings', 'calves']::muscle_group[], 'intermediate'::fitness_level, 'bodyweight_squat'::exercise_type, 'none'::equipment, ARRAY['Stand on one leg in front of a chair or box.', 'Lower the hips back and down until the glute touches the chair lightly.', 'Immediately stand back up on the same leg without pausing on the chair.']::text[], ARRAY['Touch the chair, do not sit on it.', 'Keep the knee tracking over the toes; any caving inward is a red flag.']::text[], ARRAY['Sitting on the chair, which unloads the muscles at the bottom of the range.', 'Letting the knee drift inward, which transfers the load to the knee joint.']::text[], 'Inhale as you lower, exhale as you stand.', 3, 6, null, 75, 'The knee must track the toes. If you feel it cave, stop and strengthen the glutes before continuing.'),
  ('c029a043-4d5a-5968-b905-110edb5a5412', 'Hollow Hold Rock', 'hollow-hold-rock', 'A dynamic hollow-body drill where the body rocks back and forth while maintaining the hollow shape. It teaches the core to produce force and is the honest advanced progression.', ARRAY['core']::body_part[], ARRAY['abs']::muscle_group[], ARRAY['obliques', 'erector_spine']::muscle_group[], 'advanced'::fitness_level, 'other'::exercise_type, 'none'::equipment, ARRAY['Set up in a hollow hold position with the arms by the ears and the legs straight.', 'Rock gently back to full extension without letting the shape break.', 'Return to the hollow position and repeat for the set count.']::text[], ARRAY['The body should rock as one unit; any hip or shoulder wobble breaks the shape.', 'Keep the back flat on the floor at all times.']::text[], ARRAY['Letting the lower back arch off the floor during the rock, which defeats the purpose.', 'Letting the legs separate, which makes the hollow position unstable.']::text[], 'Breathe steadily; the rocking tempo should not interrupt breathing.', 3, 10, null, 75, 'The lower back must stay on the floor throughout. If you feel it lift, shorten the range or regress to a regular hollow hold.'),
  ('b080952e-5aed-5b27-b67b-cd6191b20784', 'Plyo Push-Up (Knee-Down)', 'plyo-push-up-knee-down', 'A plyometric push-up where you push explosively enough for the hands to leave the floor. It is the most honest measure of upper-body power in a bodyweight catalog.', ARRAY['chest', 'shoulders']::body_part[], ARRAY['chest', 'triceps']::muscle_group[], ARRAY['abs', 'deltoids']::muscle_group[], 'advanced'::fitness_level, 'push_up'::exercise_type, 'none'::equipment, ARRAY['Set up in a knee push-up position.', 'Explode up so the hands leave the floor for a moment.', 'Land soft in the same position, ready for the next rep.']::text[], ARRAY['The power comes from the chest and triceps, not the hips.', 'Land with bent elbows, not straight-armed impact.']::text[], ARRAY['Pushing with the hips to fling the torso, which moves the load away from the target muscles.', 'Landing with straight elbows, which shocks the wrist and elbow joints.']::text[], 'Exhale sharply as you explode up.', 3, 5, null, 90, 'The wrist and shoulder are the weak link. Stop immediately if you feel any sharp pain. Only attempt this if regular push-ups feel easy.'),
  ('ca131abe-aa73-5318-9d44-88ec16de3933', 'Curtsy Lunge with Reach', 'curtsy-lunge-with-reach', 'A curtsy lunge with an overhead reach to load the obliques and hip stabilisers through a lateral plane of motion. It is the only catalog exercise that challenges the body in the frontal plane.', ARRAY['legs', 'core']::body_part[], ARRAY['glutes', 'adductors']::muscle_group[], ARRAY['obliques', 'calves']::muscle_group[], 'intermediate'::fitness_level, 'lunge'::exercise_type, 'none'::equipment, ARRAY['Step one leg back and across your body into a curtsy.', 'As you lunge, reach both arms overhead and lean slightly away from the working side.', 'Press through the front heel to stand; switch sides.']::text[], ARRAY['The reach should go up and away, not across; think of filling your ribcage with air.', 'Keep the front knee tracking over the toes.']::text[], ARRAY['Letting the reach become a side bend, which unloads the obliques.', 'Letting the back foot drag, which reduces the glute load.']::text[], 'Exhale as you stand, inhale as you lunge.', 3, 8, null, 60, 'The knee must track the toes in the frontal plane too. If you feel the knee cave inward, the range is too deep.'),
  ('ab4afed1-2912-5dcb-b4ea-f08dd421545e', 'Bear Crawl to Crab Walk Transition', 'bear-crawl-to-crab-walk-transition', 'A floor drill that links two locomotion patterns — bear crawl forward and crab walk backward — to load the shoulders, core, and hip flexors through a transition. It is the honest advanced locomotion entry.', ARRAY['full_body']::body_part[], ARRAY['deltoids', 'hip_flexors']::muscle_group[], ARRAY['abs', 'triceps', 'glutes']::muscle_group[], 'advanced'::fitness_level, 'locomotion'::exercise_type, 'none'::equipment, ARRAY['Bear crawl forward for five steps, keeping the hips low and level.', 'Transition to a crab walk position (back up, feet flat, hands behind).', 'Crab walk backward for five steps without letting the hips sink.', 'Transition back and repeat.']::text[], ARRAY['Keep the hips level in both modes; any rotation is a loss of control.', 'In the crab walk, press the floor away hard to keep the shoulders stable.']::text[], ARRAY['Letting the hips drop in the crab walk, which unloads the shoulder.', 'Rushing the transition, which lets form collapse under speed.']::text[], 'Breathe steadily; the transition should feel like a breath hold.', 3, null, 30, 90, 'The shoulder and wrist are under full load in both modes. Stop if you feel any pinch. Warm the shoulders thoroughly before this.')
on conflict (id) do update set
  name                   = excluded.name,
  slug                   = excluded.slug,
  description            = excluded.description,
  body_parts             = excluded.body_parts,
  primary_muscles        = excluded.primary_muscles,
  secondary_muscles      = excluded.secondary_muscles,
  difficulty             = excluded.difficulty,
  exercise_type          = excluded.exercise_type,
  equipment_required     = excluded.equipment_required,
  instructions           = excluded.instructions,
  form_cues              = excluded.form_cues,
  common_mistakes        = excluded.common_mistakes,
  breathing_instruction  = excluded.breathing_instruction,
  recommended_sets       = excluded.recommended_sets,
  recommended_reps       = excluded.recommended_reps,
  recommended_duration   = excluded.recommended_duration,
  recommended_rest       = excluded.recommended_rest,
  safety_notes           = excluded.safety_notes;

commit;
